fn main() {
  newr_rt::gset(&resp, newr_http::http_get(&("http://127.0.0.1:8080/todos".to_string()), 10, &(newr_rt::Dict::new()), |_s: i64, _h: newr_rt::Dict<String>, _b: String| HttpResponse { status: _s, headers: _h, body: _b }));
  newr_rt::gset(&todos, newr_json::json_decode(&(newr_rt::gget(&resp).body), &newr_json::Shape::List(&newr_json::Shape::Struct("Todo", &[("id", &newr_json::Shape::Int), ("title", &newr_json::Shape::Str), ("done", &newr_json::Shape::Bool)])), |_j: newr_json::JVal| { let _v = _j; newr_json::into_list(_v).into_iter().map(|_e| { let _v = _e; Todo { id: newr_json::as_int(&newr_json::field(&_v, "id")), title: newr_json::as_str(&newr_json::field(&_v, "title")), done: newr_json::as_bool(&newr_json::field(&_v, "done")) } }).collect() }));
  println!("{}", "todos:".to_string());
  for mut todo in newr_rt::gget(&todos).iter().cloned() {
    println!("{}", todo.title);
  }
  newr_rt::gset(&fresh, Todo { id: 3, title: "baca buku".to_string(), done: false });
  newr_rt::gset(&created, newr_http::http_post(&("http://127.0.0.1:8080/todos".to_string()), &({ let _newr_t0 = newr_rt::gget(&fresh); newr_json::json_encode(&newr_json::Shape::Struct("Todo", &[("id", &newr_json::Shape::Int), ("title", &newr_json::Shape::Str), ("done", &newr_json::Shape::Bool)]), { let _s = _newr_t0; newr_json::JVal::Obj(vec![("id".to_string(), newr_json::JVal::Int(_s.id)), ("title".to_string(), newr_json::JVal::Str(_s.title)), ("done".to_string(), newr_json::JVal::Bool(_s.done))]) }) }), 10, &(newr_rt::Dict::new()), |_s: i64, _h: newr_rt::Dict<String>, _b: String| HttpResponse { status: _s, headers: _h, body: _b }));
  newr_rt::print(&[newr_rt::to_str(&newr_rt::gget(&created).status)]);
  newr_rt::gset(&echoed, newr_json::json_decode(&(newr_rt::gget(&created).body), &newr_json::Shape::Struct("Todo", &[("id", &newr_json::Shape::Int), ("title", &newr_json::Shape::Str), ("done", &newr_json::Shape::Bool)]), |_j: newr_json::JVal| { let _v = _j; Todo { id: newr_json::as_int(&newr_json::field(&_v, "id")), title: newr_json::as_str(&newr_json::field(&_v, "title")), done: newr_json::as_bool(&newr_json::field(&_v, "done")) } }));
  println!("{}", "created:".to_string());
  println!("{}", newr_rt::gget(&echoed).title);
}
